MERGE sales.PaymentMethods t USING(VALUES('CASH','Cash',0,1),('UPI','UPI',1,2),('CARD','Card',1,3),('BANK','Bank Transfer',1,4),('WALLET','Wallet',1,5),('CREDIT','Credit Sale',0,6))s(MethodCode,MethodName,RequiresReference,DisplayOrder)ON t.MethodCode=s.MethodCode WHEN MATCHED THEN UPDATE SET MethodName=s.MethodName,RequiresReference=s.RequiresReference,DisplayOrder=s.DisplayOrder,IsActive=1 WHEN NOT MATCHED THEN INSERT(MethodCode,MethodName,RequiresReference,DisplayOrder)VALUES(s.MethodCode,s.MethodName,s.RequiresReference,s.DisplayOrder);
